const badge_screen_def_t *badge_screen_def(int screen)
{
    if (screen < 0 || screen >= BADGE_SCREEN_COUNT_SPEC) return 0;
    return &badge_screens[screen];
}

const badge_care_def_t *badge_care_def(int care)
{
    if (care < 0 || care >= BADGE_CARE_COUNT_SPEC) return 0;
    return &badge_care_defs[care];
}

